SELECT p.first_name, p.last_name, m.minutes, m.round FROM players p JOIN matches m ON p.player_id = m.loser_id ORDER BY m.minutes DESC LIMIT 100;
SELECT winner_name, loser_name FROM matches INNER JOIN players ON matches.loser_id = players.player_id WHERE matches.best_of = (SELECT MAX(minutes) FROM matches) GROUP BY winner_name, loser_name
SELECT players.first_name, AVG(matches.loser_rank) AS average_ranking FROM players JOIN matches ON matches.loser_id = players.player_id;
SELECT p.first_name, AVG(r.rankings_points) AS average_rankings FROM players p JOIN rankings r ON p.player_id = r.player_id GROUP BY p.first_name;
SELECT players.first_name, players.last_name, SUM(ranking_points) AS total_ranking_points FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.first_name, players.last_name
SELECT players.first_name, players.last_name, players.rankings.ranking_points AS total_ranking_points FROM players INNER JOIN rankings ON players.player_id = rankings.player_id;
SELECT COUNT(DISTINCT players.country_code) FROM players;
SELECT country_code, COUNT(player_id) AS count FROM players GROUP BY country_code
SELECT country_code FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY country_code ORDER BY ranking_points DESC LIMIT 1
SELECT country_code FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY country_code ORDER BY ranking_points DESC LIMIT 1;
SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = '2023' AND matches.minutes > 50000;
SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = (SELECT MAX(round) FROM matches WHERE round IS NOT NULL AND matches.round > 50)
SELECT COUNT(*) AS total_tours FROM rankings JOIN matches ON rankings.player_id = matches.loser_id;
SELECT DISTINCT players.player_id, rankings.ranking, rankings.ranking_points, COUNT(*) AS total_tours_per_ranking_date FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.player_id, rankings.ranking_date;
SELECT year, COUNT(*) AS count_of_matches FROM matches GROUP BY year;
SELECT year, COUNT(*) AS total_matches FROM matches GROUP BY year
SELECT p.first_name, p.rankings.ranking FROM players p JOIN rankings ON p.player_id = rankings.player_id ORDER BY p.rankings.ranking ASC LIMIT 3;
SELECT p.first_name, p.last_name, r.ranking FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking ASC LIMIT 3;
SELECT COUNT(DISTINCT players.player_id) FROM players INNER JOIN matches ON players.player_id = matches.winner_id INNER JOIN rankings ON players.player_id = rankings.player_id WHERE rankings.ranking = 'left-handed'
SELECT COUNT(DISTINCT players.player_id) FROM players JOIN matches ON players.player_id = matches.winner_id
SELECT players.first_name, players.birth_date, matches.winner_rank_points FROM players JOIN matches ON players.player_id = matches.winner_id WHERE matches.winner_rank_points ORDER BY matches.winner_rank_points DESC;
SELECT players.first_name, players.last_name, matches.winner_rank_points AS winner_rank_points FROM players INNER JOIN matches ON matches.winner_id = players.player_id WHERE matches.winner_rank_points ORDER BY winner_rank_points DESC;
SELECT COUNT(DISTINCT players.hand) AS number_of_players_per_hand_type FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY hand;
SELECT hand, COUNT(*) AS count FROM players JOIN matches ON players.player_id = matches.loser_id GROUP BY hand
