SELECT DISTINCT Addresses.line_1, Addresses.line_2, Addresses.line_3, Addresses.city, Addresses.zip_postcode FROM Addresses;
SELECT COUNT(*) FROM show WHERE show.If_first_show = '1' AND show.Performance_ID IN (SELECT Performance_ID FROM performance WHERE Performance.Type = 'Show' AND Performance.Orchestra_ID IN (SELECT Orchestra_ID FROM orchestra WHERE Orchestra.Conductor_ID IN (SELECT Conductor_ID FROM conductor WHERE conductor.Nationality = 'US') AND orchestra.Found_year = 2020)
SELECT COUNT(*) FROM conductor;
