SELECT orchestra.Orchestra, conductor.Name, orchestra.Year_of_Founded, conductor.Nationality, orchestra.Record_Company FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY orchestra.Year_of_Founded DESC;
SELECT AVG(show.Attendance) AS average_attendance FROM show INNER JOIN performance ON show.Performance_ID = performance.Performance_ID INNER JOIN orchestra ON performance.Orchestra_ID = orchestra.Orchestra_ID INNER JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID;
SELECT AVG(show.Attendance) AS average_attendance FROM show INNER JOIN performance ON show.Performance_ID = performance.Performance_ID INNER JOIN orchestra ON performance.Orchestra_ID = orchestra.Orchestra_ID INNER JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID;
