SELECT Name FROM conductor WHERE Year_of_Work IS NOT NULL AND Year_of_Work IN (SELECT Year_of_Work FROM performance JOIN orchestra ON performance.Orchestra_ID = orchestra.Orchestra_ID AND orchestra.Orchestra_ID IN (SELECT Orchestra_ID FROM orchestra JOIN conductor ON conductor.Conductor_ID = orchestra.Conductor_ID GROUP BY conductor.Conductor_ID HAVING COUNT(*) > 1))
SELECT conductor.Name, orchestra.Orchestra_ID FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID GROUP BY conductor.Conductor_ID ORDER BY orchestra.Orchestra_ID DESC;
SELECT Name, COUNT(*) AS Total_Orchestras FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID GROUP BY Name ORDER BY Total_Orchestras DESC;
