SELECT conductor.Name FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID JOIN show ON performance.Performance_ID = show.Performance_ID WHERE show.If_first_show = '1' AND show.Record_Company = 'latest orchestras' ORDER BY conductor.Name
SELECT DISTINCT conductor.Name, orchestra.Record_Company, orchestra.Orchestra_ID FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;
SELECT COUNT(DISTINCT orchestra.Orchestra_ID) FROM orchestra;
SELECT orchestra.Major_Record_Format FROM orchestra ORDER BY orchestra.Year_of_Founded ASC;
SELECT orchestra.Major_Record_Format, orchestra.Year_of_Founded, conductor.Name, conductor.birthday, conductor.Nationality, orchestra.Record_Company, orchestra.Orchestra, performance.Type, performance.Weekly_rank, performance.Share FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON performance.Orchestra_ID = orchestra.Orchestra_ID JOIN show ON show.Performance_ID = performance.Performance_ID WHERE orchestra.Major_Record_Format IS NOT NULL ORDER BY orchestra.Year_of_Founded ASC;
SELECT orchestra.Orchestra, conductor.Name, conductor.birthday, conductor.Nationality, conductor.Year_of_Work, orchestra.Record_Company, orchestra.Year_of_Founded, orchestra.Major_Record_Format FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID WHERE orchestra.Year_of_Founded IS NOT NULL ORDER BY conductor.birthday ASC LIMIT 10
