SELECT performance.Type, performance.Performance_ID FROM performance JOIN show ON performance.Performance_ID = show.Performance_ID JOIN orchestra ON performance.Orchestra_ID = orchestra.Orchestra_ID JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE show.If_first_show = 'No' AND performance.Weekly_rank > 1;
