SELECT Owners.state, Professionals.state FROM Owners INNER JOIN Professionals ON Owners.owner_id = Professionals.owner_id WHERE Dogs.abandoned_yn = 'N' AND Dogs.breed_code = Breeds.breed_code AND Dogs.size_code = Sizes.size_code AND Treatments.treatment_type_code = Treatment_Types.treatment_type_code AND Treatments.professional_id = Professionals.professional_id
