SELECT Professionals.professional_id, Professionals.last_name, Professionals.cell_number FROM Professionals INNER JOIN Treatments ON Professionals.professional_id = Treatments.professional_id INNER JOIN Dogs ON Dogs.dog_id = Treatments.dog_id WHERE Professionals.state = 'Indiana' OR Treatments.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_description = 'more than two treatments')
