SELECT DISTINCT o.first_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.professional_id = p.professional_id WHERE p.role_code = 'Professional' OR p.role_code = 'Owner' AND d.abandoned_yn = 'N' AND d.name NOT IN ('dog_name')
SELECT Dogs.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.abandoned_yn = 'N' AND Dogs.name IS NOT NULL AND Dogs.breed_code IN (SELECT breed_code FROM Breeds WHERE breed_code = (SELECT breed_code FROM Breeds WHERE breed_name = 'Professional' OR breed_name = 'Owner')) AND Dogs.gender IS NOT NULL;
