SELECT Professionals.professional_id, Owners.street, Owners.cell_number FROM Professionals INNER JOIN Owners ON Professionals.professional_id = Owners.owner_id WHERE Owners.adopted_yn = 'Y' AND Professionals.role_code = 'P' AND Professionals.treatment_type_code = 'T' AND Professionals.home_phone = 'Y'
SELECT p.professional_id, p.first_name, p.last_name, t.treatment_type_description, t.date_of_treatment, t.cost_of_treatment FROM Professionals p JOIN Treatments t ON p.professional_id = t.professional_id WHERE t.treatment_type_code IN (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_description = 'Two or More Treatments')
