SELECT Dogs.owner_id, Dogs.zip_code FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id INNER JOIN Treatments ON Treatments.dog_id = Dogs.dog_id INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code INNER JOIN Breeds ON Dogs.breed_code = Breeds.breed_code INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code ORDER BY Dogs.owner_id, Dogs.zip_code DESC;
SELECT Professionals.professional_id, Professionals.first_name, Professionals.last_name FROM Professionals INNER JOIN Dogs ON Dogs.owner_id = Professionals.owner_id INNER JOIN Owners ON Owners.owner_id = Professionals.owner_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code INNER JOIN Charges ON Charges.charge_id = Treatments.cost_of_treatment INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code INNER JOIN Breeds ON Dogs.breed_code = Breeds.breed_code;
SELECT Professionals.professional_id, Dogs.dog_id, Treatment_Types.treatment_type_code, Treatments.date_of_treatment, Treatments.cost_of_treatment FROM Professionals INNER JOIN Treatments ON Professionals.professional_id = Treatments.professional_id INNER JOIN Dogs ON Treatments.dog_id = Dogs.dog_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Professionals.role_code = 'Professional' AND Dogs.abandoned_yn = 'Y' AND Professionals.role_code = 'Professional' AND Treatments.cost_of_treatment IS NOT NULL;
SELECT d.name, p.first_name, p.last_name, p.email_address, p.home_phone, p.cell_number FROM Dogs d JOIN Professionals p ON d.owner_id = p.owner_id WHERE d.cost_of_treatment < (SELECT AVG(cost_of_treatment) FROM Charges) GROUP BY d.name, p.first_name, p.last_name, p.email_address, p.home_phone, p.cell_number;
SELECT o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Professionals p ON t.professional_id = p.professional_id WHERE t.cost_of_treatment < (SELECT AVG(cost_of_treatment) FROM Charges) GROUP BY o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number
SELECT Dogs.date_of_birth, Professionals.first_name, Professionals.last_name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.date_of_birth IS NOT NULL;
SELECT Dogs.name, Professionals.first_name, Professionals.last_name, Treatments.date_of_treatment FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Charges.charge_amount FROM Dogs JOIN Charges ON Dogs.owner_id = Charges.charge_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Charges.charge_amount AS cost_of_treatment FROM Dogs INNER JOIN Charges ON Dogs.dog_id = Charges.charge_id INNER JOIN Treatment_Types ON Charges.charge_type = Treatment_Types.treatment_type_code;
